def gcdSort(nums):
    # Helper function: Sieve up to max(nums)
    def get_spf(limit):
        spf = [0] * (limit + 1)
        for i in range(2, limit + 1):
            if spf[i] == 0:
                for j in range(i, limit + 1, i):
                    if spf[j] == 0:
                        spf[j] = i
        return spf

    class DSU:
        def __init__(self, size):
            self.parent = list(range(size))
        def find(self, x):
            while self.parent[x] != x:
                self.parent[x] = self.parent[self.parent[x]]
                x = self.parent[x]
            return x
        def union(self, x, y):
            fx, fy = self.find(x), self.find(y)
            if fx != fy:
                self.parent[fx] = fy

    n = len(nums)
    MAX = max(nums)
    spf = get_spf(MAX)  # smallest prime factor for all numbers up to MAX
    dsu = DSU(MAX + 1)

    # Union each value with its prime factors (all numbers sharing a factor >1 get connected)
    for x in nums:
        num = x
        while num > 1:
            fac = spf[num]
            dsu.union(x, fac)
            while num % fac == 0:
                num //= fac

    sorted_nums = sorted(nums)
    for x, y in zip(nums, sorted_nums):
        if dsu.find(x) != dsu.find(y):
            return False
    return True
